SELECT COUNT(*)
FROM attendance_policy_scoped_version version
JOIN attendance_policy_scope scope ON scope.scope_id = version.scope_id
WHERE scope.policy_template_id = #{templateId}
  AND scope.legal_entity_id = #{legalEntityId}

SELECT 
FROM attendance_policy_scoped_version version
JOIN attendance_policy_scope scope ON scope.scope_id = version.scope_id
JOIN attendance_policy_template template
  ON template.policy_template_id = scope.policy_template_id
WHERE scope.policy_template_id = #{templateId}
  AND scope.legal_entity_id = #{legalEntityId}
ORDER BY version.version_number DESC, version.scoped_version_id
LIMIT #{limit} OFFSET #{offset}

SELECT 
FROM attendance_policy_scoped_version version
JOIN attendance_policy_scope scope ON scope.scope_id = version.scope_id
JOIN attendance_policy_template template
  ON template.policy_template_id = scope.policy_template_id
WHERE scope.policy_template_id = #{templateId}
  AND scope.legal_entity_id = #{legalEntityId}
  AND version.scoped_version_id = #{scopedVersionId}

SELECT COALESCE(MAX(version_number), 0)
FROM attendance_policy_scoped_version
WHERE scope_id = #{scopeId}

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM attendance_policy_lifecycle_event publication
    WHERE publication.scope_id = #{scopeId}
      AND publication.action = 'PUBLISHED'
      AND publication.business_effective_from
            >= #{businessEffectiveFrom}
) THEN TRUE ELSE FALSE END

